//! Cross-language contract.
//!
//! Every case in tests/fixtures/contract.json was generated by the Python
//! implementation, which stays the source of truth. If this test fails, the Rust
//! port has drifted from Python - not the other way around.

use neverkickoff::device::{Device, DeviceError};
use neverkickoff::engine::Engine;
use neverkickoff::hotkeys::format_hotkey;
use neverkickoff::keys::{parse_combo, parse_combo_parts, Key};
use neverkickoff::spec::{load_spec, normalize_steps};
use neverkickoff::window::{as_text, RawTitle};
use neverkickoff::ydotool::keycode;
use serde_json::{json, Value};
use std::sync::Arc;

fn fixture() -> Value {
    let path = std::path::Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("..")
        .join("tests")
        .join("fixtures")
        .join("contract.json");
    let text = std::fs::read_to_string(&path)
        .unwrap_or_else(|error| panic!("cannot read {}: {}", path.display(), error));
    serde_json::from_str(&text).expect("contract.json is not valid JSON")
}

/// Collect every mismatch, then fail once with all of them.
#[derive(Default)]
struct Report {
    failures: Vec<String>,
}

impl Report {
    fn check(&mut self, label: &str, actual: Value, expected: Value) {
        if actual != expected {
            self.failures.push(format!(
                "{}:\n    rust     {:?}\n    contract {:?}",
                label, actual, expected
            ));
        }
    }

    fn finish(self) {
        assert!(
            self.failures.is_empty(),
            "Rust drifted from the Python contract:\n  {}",
            self.failures.join("\n  ")
        );
    }
}

fn parts_of(value: &Value) -> Vec<String> {
    value
        .as_array()
        .expect("combo list")
        .iter()
        .map(|item| item.as_str().expect("combo part").to_string())
        .collect()
}

#[test]
fn normalize_steps_matches_python() {
    let contract = fixture();
    let mut report = Report::default();
    for (index, case) in contract["normalize_steps"]
        .as_array()
        .unwrap()
        .iter()
        .enumerate()
    {
        let actual = serde_json::to_value(normalize_steps(&case["spec"])).unwrap();
        report.check(
            &format!("normalize_steps[{}]", index),
            actual,
            case["expect"].clone(),
        );
    }
    report.finish();
}

#[test]
fn parse_combo_matches_python() {
    let contract = fixture();
    let mut report = Report::default();
    for (index, case) in contract["parse_combo"]
        .as_array()
        .unwrap()
        .iter()
        .enumerate()
    {
        let combo = &case["combo"];
        let parsed = match combo.as_str() {
            Some(text) => parse_combo(text),
            None => parse_combo_parts(&parts_of(combo)),
        };
        let (value, error) = match parsed {
            Ok(keys) => (serde_json::to_value(keys).unwrap(), Value::Null),
            Err(failure) => (Value::Null, json!(failure.message)),
        };
        report.check(
            &format!("parse_combo[{}] keys", index),
            value,
            case["expect"].clone(),
        );
        report.check(
            &format!("parse_combo[{}] error", index),
            error,
            case["error"].clone(),
        );
    }
    report.finish();
}

