#[test]
fn format_hotkey_matches_python() {
    let contract = fixture();
    let mut report = Report::default();
    for (index, case) in contract["format_hotkey"]
        .as_array()
        .unwrap()
        .iter()
        .enumerate()
    {
        let keysym = case["keysym"].as_str().unwrap();
        let state = case["state"].as_u64().unwrap() as u32;
        let value = match format_hotkey(keysym, state) {
            Some(text) => json!(text),
            None => Value::Null,
        };
        report.check(
            &format!("format_hotkey[{}]", index),
            value,
            case["expect"].clone(),
        );
    }
    report.finish();
}

#[test]
fn as_text_matches_python() {
    let contract = fixture();
    let mut report = Report::default();
    for (index, case) in contract["as_text"].as_array().unwrap().iter().enumerate() {
        let value = &case["value"];
        let bytes: Vec<u8>;
        let raw = match value["kind"].as_str().unwrap() {
            "bytes" => {
                bytes = value["data"]
                    .as_array()
                    .unwrap()
                    .iter()
                    .map(|item| item.as_u64().unwrap() as u8)
                    .collect();
                RawTitle::Bytes(&bytes)
            }
            "str" => RawTitle::Text(value["data"].as_str().unwrap()),
            _ => RawTitle::Unavailable,
        };
        let actual = match as_text(raw) {
            Some(text) => json!(text),
            None => Value::Null,
        };
        report.check(
            &format!("as_text[{}]", index),
            actual,
            case["expect"].clone(),
        );
    }
    report.finish();
}

#[test]
fn keycode_matches_python() {
    let contract = fixture();
    let mut report = Report::default();
    for (index, case) in contract["keycode"].as_array().unwrap().iter().enumerate() {
        let key: Key = serde_json::from_value(case["key"].clone()).expect("fixture key");
        let (value, kind) = match keycode(&key) {
            Ok(code) => (json!(code), Value::Null),
            Err(_) => (Value::Null, json!("ValueError")),
        };
        report.check(
            &format!("keycode[{}] value", index),
            value,
            case["expect"].clone(),
        );
        report.check(
            &format!("keycode[{}] error", index),
            kind,
            case["error_kind"].clone(),
        );
    }
    report.finish();
}

/// Records every call, and fails on the Nth key press like the Python FakeDevice.
struct Recorder {
    events: Vec<(String, String)>,
    fail_on: Option<usize>,
    presses: usize,
}

impl Recorder {
    fn new(fail_on: Option<usize>) -> Self {
        Recorder {
            events: Vec::new(),
            fail_on,
            presses: 0,
        }
    }

    fn record(&mut self, kind: &str, token: String) {
        self.events.push((kind.to_string(), token));
    }
}

impl Device for Recorder {
    fn mouse_press(&mut self, button: &str) -> Result<(), DeviceError> {
        self.record("mouse_press", button.to_string());
        Ok(())
    }

    fn mouse_release(&mut self, button: &str) -> Result<(), DeviceError> {
        self.record("mouse_release", button.to_string());
        Ok(())
    }

    fn key_press(&mut self, key: &Key) -> Result<(), DeviceError> {
        if let Some(limit) = self.fail_on {
            self.presses += 1;
            if self.presses == limit {
                return Err(DeviceError("device failure".to_string()));
            }
        }
        self.record("key_press", key.token());
        Ok(())
    }

    fn key_release(&mut self, key: &Key) -> Result<(), DeviceError> {
        self.record("key_release", key.token());
        Ok(())
    }
}

#[test]
fn engine_matches_python() {
    let contract = fixture();
    let mut report = Report::default();
    for (index, case) in contract["engine"].as_array().unwrap().iter().enumerate() {
        let spec = case["spec"].clone();
        let focused = case["focused"].as_str().map(|text| text.to_string());
        let fail_on = case["fail_on"].as_u64().map(|n| n as usize);
        let mut engine = Engine::new(
            Recorder::new(fail_on),
            Some(Arc::new(move || focused.clone())),
        );
        let result = engine.run(&spec);

        let events: Vec<Value> = engine
            .device()
            .events
            .iter()
            .map(|(kind, token)| json!([kind, token]))
            .collect();
        report.check(
            &format!("engine[{}] events", index),
            Value::Array(events),
            case["expect_events"].clone(),
        );
        let (fired, error) = match result {
            Ok(count) => (json!(count as i64), Value::Null),
            Err(_) => (Value::Null, json!("RuntimeError")),
        };
        report.check(
            &format!("engine[{}] fired", index),
            fired,
            case["expect_fired"].clone(),
        );
        report.check(
            &format!("engine[{}] error", index),
            error,
            case["expect_error_kind"].clone(),
        );
    }
    report.finish();
}
